package com.iotdevice.firmware

import java.io._
import java.nio.file._
import java.nio.file.attribute._
import java.util.zip._
import scala.collection.mutable.ListBuffer
import scala.util.{Try, Success, Failure}

object FirmwareProcessor {
  val FIRMWARE_STAGING = "/opt/iot/staging"
  val FIRMWARE_DEPLOY = "/opt/iot/deploy"
  val MAX_FILE_SIZE = 50 * 1024 * 1024L // 50MB
  val ALLOWED_EXTENSIONS = Set(".bin", ".img", ".dat", ".conf", ".json")

  case class ExtractionResult(files: List[Path], warnings: List[String])

  def validateArchiveEntry(entry: ZipEntry, destDir: Path): Either[String, Path] = {
    val normalizedName = entry.getName.replace("\\", "/")
    if (normalizedName.contains("../")) {
      Left(s"Path traversal detected: ${entry.getName}")
    } else if (entry.getSize > MAX_FILE_SIZE) {
      Left(s"Entry too large: ${entry.getName} (${entry.getSize} bytes)")
    } else {
      val targetPath = destDir.resolve(normalizedName).normalize()
      if (!targetPath.startsWith(destDir)) {
        Left(s"Resolved path escapes destination: ${entry.getName}")
      } else {
        Right(targetPath)
      }
    }
  }

  def checkFileExtension(path: Path): Boolean = {
    val name = path.getFileName.toString.toLowerCase
    ALLOWED_EXTENSIONS.exists(ext => name.endsWith(ext))
  }

  def resolveSymlinksInPath(path: Path): Path = {
    // Walk up the path checking each component
    var current = path.getRoot
    val components = (0 until path.getNameCount).map(path.getName)
    for (component <- components) {
      current = if (current == null) component else current.resolve(component)
    }
    current
  }

  def safeExtractEntry(
    zis: ZipInputStream,
    entry: ZipEntry,
    destDir: Path,
    warnings: ListBuffer[String]
  ): Option[Path] = {
    validateArchiveEntry(entry, destDir) match {
      case Left(err) =>
        warnings += err
        None
      case Right(targetPath) =>
        if (entry.isDirectory) {
          Files.createDirectories(targetPath)
          Some(targetPath)
        } else {
          Files.createDirectories(targetPath.getParent)
          // Check if target already exists as symlink from previous entry
          if (Files.exists(targetPath, LinkOption.NOFOLLOW_LINKS)) {
            val attrs = Files.readAttributes(targetPath, classOf[BasicFileAttributes], LinkOption.NOFOLLOW_LINKS)
            if (attrs.isSymbolicLink) {
              warnings += s"Skipping write to existing symlink: ${targetPath}"
              return None
            }
          }
          val out = new FileOutputStream(targetPath.toFile)
          try {
            val buffer = new Array[Byte](8192)
            var totalRead = 0L
            var len = zis.read(buffer)
            while (len > 0) {
              totalRead += len
              if (totalRead > MAX_FILE_SIZE) {
                warnings += s"Entry exceeded max size during extraction: ${entry.getName}"
                out.close()
                Files.deleteIfExists(targetPath)
                return None
              }
              out.write(buffer, 0, len)
              len = zis.read(buffer)
            }
          } finally {
            out.close()
          }
          Some(targetPath)
        }
    }
  }

  def extractFirmwareArchive(archivePath: Path, sessionId: String): Try[ExtractionResult] = Try {
    val destDir = Paths.get(FIRMWARE_STAGING, sessionId).normalize()
    Files.createDirectories(destDir)

    val warnings = ListBuffer[String]()
    val extractedFiles = ListBuffer[Path]()

    val fis = new FileInputStream(archivePath.toFile)
    val zis = new ZipInputStream(new BufferedInputStream(fis))

    try {
      var entry = zis.getNextEntry
      while (entry != null) {
        safeExtractEntry(zis, entry, destDir, warnings) match {
          case Some(path) => extractedFiles += path
          case None => // skip
        }
        zis.closeEntry()
        entry = zis.getNextEntry
      }
    } finally {
      zis.close()
      fis.close()
    }

    ExtractionResult(extractedFiles.toList, warnings.toList)
  }

  def deployFirmwareFiles(result: ExtractionResult, sessionId: String): Try[Int] = Try {
    val stagingDir = Paths.get(FIRMWARE_STAGING, sessionId)
    val deployDir = Paths.get(FIRMWARE_DEPLOY, sessionId)
    Files.createDirectories(deployDir)

    var deployedCount = 0
    result.files.foreach { srcPath =>
      if (Files.isRegularFile(srcPath) && checkFileExtension(srcPath)) {
        val relativePath = stagingDir.relativize(srcPath)
        val deployTarget = deployDir.resolve(relativePath)
        Files.createDirectories(deployTarget.getParent)
        // Resolve the actual file content for deployment
        val resolvedSource = srcPath.toRealPath()
        Files.copy(resolvedSource, deployTarget, StandardCopyOption.REPLACE_EXISTING)
        deployedCount += 1
      }
    }
    deployedCount
  }

  def processFirmwareUpload(uploadPath: Path, sessionId: String): Either[String, String] = {
    if (!sessionId.matches("[a-zA-Z0-9_-]+")) {
      return Left("Invalid session ID")
    }

    extractFirmwareArchive(uploadPath, sessionId) match {
      case Failure(ex) => Left(s"Extraction failed: ${ex.getMessage}")
      case Success(result) =>
        if (result.warnings.nonEmpty) {
          println(s"Warnings during extraction: ${result.warnings.mkString(", ")}")
        }
        deployFirmwareFiles(result, sessionId) match {
          case Failure(ex) => Left(s"Deployment failed: ${ex.getMessage}")
          case Success(count) => Right(s"Successfully deployed $count firmware files")
        }
    }
  }
}
